body:
{
  "pains": [
    {
      "id": "pain:false-flag-coaching",
      "statement": "The camera dings me for glancing at my own dashboard, and then I get pulled into a meeting about it.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Normal driving gets scored as a safety event: a glance at the gauges, a hard brake that avoided a collision, a rolling stop that was a full stop.",
        "operational": "Safety staff burn review time clearing events that were never risky, and coaching lands on drivers who did nothing wrong, so the score stops describing risk and starts describing camera angles.",
        "personal": "The driver stops trusting the system and starts driving to satisfy the lens instead of the road, and learns which behaviours the AI misses."
      },
      "workflow": "The event fires in the Samsara Safety Inbox with video attached, a reviewer tags or dismisses it, it moves the driver's Safety Score, and the driver gets a coaching session or a self-coaching task in the Samsara Driver app.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A rolling stop or distraction event is called wrong and the driver disputes it", "cites": ["src:2", "src:5"] },
        { "event": "Emergency braking to avoid a crash is logged as a harsh-brake violation", "cites": ["src:2"] },
        { "event": "Drivers work out how to beat the phone-detection model and the score stops meaning anything", "cites": ["src:9"] }
      ],
      "who_feels": ["end_user", "champion", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "The safety guy pulled me into a meeting because the camera caught me looking down at the dashboard twice in one day.", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "I just DO NOT understand how a company can say they are all 'safety first' and then go and penalize usage of the brake pedal.", "cites": ["src:2"] },
            { "situation": "when_it_bites", "verbatim": "Looking down at your dashboard is normal, and hitting the brakes hard to avoid an accident is safe driving, not a violation.", "cites": ["src:2"] },
            { "situation": "when_refusing", "verbatim": "The only thing that matters is playing the stupid Samsara game and hoping you get a good safety manager that leaves you alone.", "cites": ["src:2"] }
          ],
          "costs_them": "Score-linked bonus money, a permanent record of events they did not cause, and meetings on their own time.",
          "fears": "That a pile of machine-called events becomes the paper trail used to discipline or fire them.",
          "dream_outcome": "The camera only speaks up when something actually happened, and when it does it backs the driver up."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "The only issue I have observed with our Samsara program is that it is sometimes too sensitive.", "cites": ["src:7"] },
            { "situation": "to_their_boss", "verbatim": "Every now and then a rolled stop will be miss called.", "cites": ["src:5"] },
            { "situation": "venting", "verbatim": "That's punitive. It's like, 'OK, now you're going to watch me all the time, because I messed up?'", "cites": ["src:11"] }
          ],
          "costs_them": "Credibility with the crew: every bad call spent in a coaching session is credibility they cannot get back.",
          "fears": "Becoming the person drivers see as the enforcement arm of a machine rather than a safety professional.",
          "dream_outcome": "A short, true queue of events they can defend line by line to any driver who pushes back."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "When trucking companies use AI cameras as babysitters and 'nanny cams' all they do is end up driving their best drivers out.", "cites": ["src:2"] }
          ],
          "costs_them": "Standing with the people they represent, if they sign off on a system the crew reads as harassment.",
          "fears": "That the rollout costs the shop its most experienced hands.",
          "dream_outcome": "Thresholds set with drivers in the room and a real appeal path on every event."
        }
      },
      "segments": ["seg:trucking", "seg:construction", "seg:public"],
      "feature_ref": "feat:cameras",
      "cites": ["src:2", "src:5", "src:7", "src:9", "src:11"]
    },
    {
      "id": "pain:coaching-backlog",
      "statement": "We review footage every day, and there is no way a safety department our size sits down with every driver.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "The event queue grows faster than anyone can work it, so coaching gets skipped, batched, or handed back to the driver to do alone.",
        "operational": "Events age out unreviewed, video retention windows close on the clips that mattered, and the program quietly becomes a recording system rather than a coaching system.",
        "personal": "The safety lead knows the backlog is the thing that will be held against them after a crash, and cannot clear it."
      },
      "workflow": "Daily pass through the Samsara Safety Inbox, triage by severity, assign coaching sessions in the Samsara dashboard, then chase drivers to complete self-coaching in the Driver app between loads.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Event volume outruns the safety team after a fleet-wide camera rollout", "cites": ["src:7"] },
        { "event": "Download and retention limits force a rethink of the whole review process", "cites": ["src:7"] },
        { "event": "Real-time alerts turn out to be inconsistent and a real incident arrives with no notification", "cites": ["src:7"] }
      ],
      "who_feels": ["champion", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "I least like the self-coaching feature. The safety department I am in is small, and we review footage daily, but do not have the time to coach each driver", "cites": ["src:7"] },
            { "situation": "when_comparing", "verbatim": "Time limits on downloadable video caused us to reevaluate our safety review process", "cites": ["src:7"] },
            { "situation": "when_it_bites", "verbatim": "I have noticed inconsistencies with the real-time alerts. Recently, one of my drivers was involved in a car accident, but I did not receive an accident alert", "cites": ["src:7"] }
          ],
          "costs_them": "Every hour of the day, and the part of the job that actually changes behaviour.",
          "fears": "A plaintiff's attorney showing the jury a queue of unreviewed events with the same flag the crash driver had.",
          "dream_outcome": "The system triages for them, so the handful of drivers who need a human conversation get one and the rest are handled without it."
        },
        "economic_buyer": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "The driving habits of my employees have improved because they know I am watching.", "cites": ["src:6"] }
          ],
          "costs_them": "Headcount they do not have, or a safety program that is bought but not run.",
          "fears": "Paying for a platform whose value depends on labour they never budgeted.",
          "dream_outcome": "Coaching that scales without adding safety staff per hundred trucks."
        }
      },
      "segments": ["seg:trucking", "seg:public"],
      "feature_ref": "feat:workforce",
      "cites": ["src:5", "src:6", "src:7"]
    },
    {
      "id": "pain:cameras-cost-us-drivers",
      "statement": "Put an inward camera in the cab and the drivers I most want to keep start looking for another seat.",
      "element": "b2b:ease_of_doing_business:cultural_fit",
      "shape": {
        "surface": "Experienced drivers treat the driver-facing lens as a dealbreaker and filter employers by whether they run one.",
        "operational": "Recruiting narrows to the drivers who will accept it, some carriers pull the inward cameras back out, and the safety gain gets traded for churn.",
        "personal": "The driver feels watched for the whole shift and reads the camera as an accusation rather than protection."
      },
      "workflow": "The rollout meeting, the consent form, then the Samsara Driver app on every login, plus the recruiting call where a candidate asks whether the trucks have inward-facing cameras before asking about pay.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A fleet-wide inward camera install is announced", "cites": ["src:3", "src:11"] },
        { "event": "A driver cannot find a camera-free job and leaves the industry", "cites": ["src:2"] },
        { "event": "A carrier removes inward cameras after losing cases or losing drivers", "cites": ["src:4"] }
      ],
      "who_feels": ["end_user", "economic_buyer", "blocker"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_refusing", "verbatim": "I haven't been able to find a trucking job that does not have them, so I finally decided to quit trucking this past week.", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "They can look at what you're doing at anytime. Listening to what you are saying at anytime.", "cites": ["src:3"] },
            { "situation": "venting", "verbatim": "It gives an extraordinary amount of power to bad managers.", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "They certainly haven't mentioned that there is a points system that measures individuals safety and scores them.", "cites": ["src:3"] }
          ],
          "costs_them": "Privacy for eleven hours a day, and in some cases the job itself.",
          "fears": "That audio and video of an ordinary bad day gets used against them by someone who has never driven a truck.",
          "dream_outcome": "A camera that points at the road, and an inward lens that only opens when it is defending them."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_comparing", "verbatim": "TMC took the inward-facing cameras out after too many lost lawsuits/settlements", "cites": ["src:4"] },
            { "situation": "to_their_boss", "verbatim": "When you go to the whip, the race is over", "cites": ["src:11"] }
          ],
          "costs_them": "Recruiting reach and seat-fill time in a market where the experienced drivers get to choose.",
          "fears": "Winning the insurance argument and losing the crew.",
          "dream_outcome": "Drivers asking for the camera because it has already cleared one of their own."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "They are legally required to have us sign off that they have our permission", "cites": ["src:3"] },
            { "situation": "when_refusing", "verbatim": "Any trucking company that deploys this type of feature would be sued into bankruptcy.", "cites": ["src:4"] }
          ],
          "costs_them": "Trust with the workforce, and exposure under consent and privacy rules in some jurisdictions.",
          "fears": "Signing off on monitoring that was never properly disclosed or consented to.",
          "dream_outcome": "Clear disclosure, written consent, and limits on who can watch what and when."
        }
      },
      "segments": ["seg:trucking", "seg:construction"],
      "feature_ref": "feat:workforce",
      "cites": ["src:2", "src:3", "src:4", "src:11"]
    },
    {
      "id": "pain:one-crash-ends-us",
      "statement": "One bad crash with a sympathetic plaintiff and the paper record buries us, even when the driver did everything right.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "The police report and the paperwork read against the driver, and nothing in the file contradicts them.",
        "operational": "The carrier settles, fires a driver who was not at fault, or takes a verdict it cannot absorb, and the premium follows it for years.",
        "personal": "The owner or ops leader carries the decision to let a driver go on a version of events they could not check."
      },
      "workflow": "The call comes in, someone pulls the event from the Samsara dashboard, escalates by severity, and hands the clip to the claims adjuster and defence counsel in the first days after the crash.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A severe injury crash where the paperwork points at your driver", "cites": ["src:10"] },
        { "event": "A staged or opportunistic claim filed against the fleet", "cites": ["src:10"] },
        { "event": "Renewal comes back with a double-digit premium increase after industry verdicts", "cites": ["src:12"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "And if you look at all the information on paper, you would say, 'This guy is toast. He screwed up.' But when you looked at the camera data, this could easily be a training video released nationwide.", "cites": ["src:10"] },
            { "situation": "to_their_boss", "verbatim": "fired the driver immediately, and we'd probably be facing a $40 million lawsuit that we would have lost.", "cites": ["src:10"] },
            { "situation": "venting", "verbatim": "Nobody can deny the fact that our industry is targeted", "cites": ["src:12"] }
          ],
          "costs_them": "A verdict or settlement larger than the company's equity, plus the premium load afterwards.",
          "fears": "Losing the business over an event their driver did not cause.",
          "dream_outcome": "The footage in hand within the hour, and the claim ends before it becomes a case."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "As soon as they see we've got a camera, and we provide the video, it goes away.", "cites": ["src:10"] },
            { "situation": "when_it_bites", "verbatim": "I was able to review it and say to him, 'This is no minor accident. This one's bad.'", "cites": ["src:10"] }
          ],
          "costs_them": "Nights and weekends reconstructing events with no objective record.",
          "fears": "Discovering the one clip that mattered was never captured.",
          "dream_outcome": "Severity known in minutes, the right people called, and the video preserved before anyone asks for it."
        }
      },
      "segments": ["seg:trucking", "seg:construction", "seg:public"],
      "feature_ref": "feat:cameras",
      "cites": ["src:10", "src:12"]
    },
    {
      "id": "pain:video-not-there-when-needed",
      "statement": "The one clip I actually needed for a defendable claim was the clip the system could not give me.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "Footage goes black, the gateway drops signal, retrieval takes hours, or the window has already closed.",
        "operational": "A claim that was winnable gets paid, retrieval turns into a support ticket chain, and someone drives out to physically unplug hardware to get a camera back online.",
        "personal": "The person who promised the platform would protect the company has to explain why it did not this time."
      },
      "workflow": "Request the clip in the Samsara dashboard by vehicle and timestamp, wait for upload over cellular, then chase support when the download limit, retention window, or a firmware fault gets in the way.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A firmware or hardware fault destroys the footage from an accident", "cites": ["src:6"] },
        { "event": "A driver is out of coverage when the event fires", "cites": ["src:5"] },
        { "event": "Retrieval limits or retention windows block the download a claim needs", "cites": ["src:6", "src:7"] }
      ],
      "who_feels": ["champion", "technical_evaluator", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "The footage goes black sometimes. Sometimes loses connection when a driver is out of town.", "cites": ["src:5"] },
            { "situation": "when_it_bites", "verbatim": "The video retrieval process could be a little easier to navigate and it would be nice to have a live view feature", "cites": ["src:7"] }
          ],
          "costs_them": "The defence in the one case that mattered.",
          "fears": "Finding out mid-claim that the footage never existed.",
          "dream_outcome": "Every severe event preserved automatically and retrievable in full, without a ticket."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "We even had a situation we were unable to retrive video of an accident due to a firmware failure. This ended up costing us thousands of dollars for defendable accident claim.", "cites": ["src:6"] },
            { "situation": "venting", "verbatim": "Won't give us address to sent camera to get footage 14 days been waiting", "cites": ["src:6"] }
          ],
          "costs_them": "Hard dollars on a claim they should have won, on top of the subscription.",
          "fears": "That the whole safety investment fails at the exact moment it is needed.",
          "dream_outcome": "Footage availability they can count on without checking."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Camera sometimes lose picture., and we have to physically unplug the gateway to make it work.", "cites": ["src:6"] }
          ],
          "costs_them": "Truck-roll time to reseat hardware that should recover on its own.",
          "fears": "Silent device failures nobody notices until an incident.",
          "dream_outcome": "Health monitoring that flags a dead camera the day it dies, and a remote reboot."
        }
      },
      "segments": ["seg:trucking", "seg:construction", "seg:public"],
      "feature_ref": "feat:cameras",
      "cites": ["src:5", "src:6", "src:7"]
    },
    {
      "id": "pain:cost-per-mile-squeeze",
      "statement": "Insurance, parts and labour all keep climbing, and the only lever I have left is proving my people are the safe ones.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "Every line on the cost-per-mile sheet moved the wrong way, and rates did not follow.",
        "operational": "Maintenance, fuel and insurance get managed by hand across separate systems while margin thins, so decisions get made on stale numbers.",
        "personal": "The ops leader has to justify a premium software line item in the same year they are cutting everywhere else."
      },
      "workflow": "Monthly cost review against fuel card statements, maintenance invoices and the Samsara reports, then the renewal meeting with the insurer where the safety and telematics record is the argument.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Insurance renewal with a premium increase", "cites": ["src:13", "src:12"] },
        { "event": "Repair and maintenance cost per mile jumps year over year", "cites": ["src:13"] },
        { "event": "Fleet is asked to cut cost while keeping the same service levels", "cites": ["src:8"] }
      ],
      "who_feels": ["economic_buyer", "technical_evaluator"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "venting", "verbatim": "For every dollar of revenue that [trucking companies] make, 90 cents of it goes to cover their costs", "cites": ["src:12"] },
            { "situation": "when_comparing", "verbatim": "Samsara is a premium price - it gets expensive for small fleets - but the biggest issue is that they continue to come out with features and want to nickel and dime for every feature", "cites": ["src:7"] }
          ],
          "costs_them": "Margin, in a business where the cost side is mostly fixed by fuel, labour and insurance.",
          "fears": "Paying premium software prices and still taking the premium increase.",
          "dream_outcome": "A safety and utilisation record good enough to argue the renewal down, with the numbers in one place."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "accurate fuel and repair cost tracking. Generating reports through excel worksheets. Logging information can be tricky for non techy users", "cites": ["src:7"] }
          ],
          "costs_them": "Days a month rebuilding cost reports in spreadsheets.",
          "fears": "Presenting numbers they cannot fully defend.",
          "dream_outcome": "Fuel, maintenance and utilisation cost per unit straight out of the platform."
        }
      },
      "segments": ["seg:trucking", "seg:construction", "seg:public"],
      "feature_ref": "feat:telematics",
      "cites": ["src:7", "src:12", "src:13"]
    },
    {
      "id": "pain:unassigned-drive-time",
      "statement": "Before an audit I am hand-assigning unassigned drive time, and one platform update wiped out corrections I had already made.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "Unidentified driving segments, log edits and fuel tax reporting all need manual cleanup that never ends.",
        "operational": "Unresolved unassigned time is a documented red flag in a compliance review, so the work has to be redone whenever data is lost, and an audit stretches out while an investigator sorts through gaps.",
        "personal": "The compliance coordinator personally owns a finding that lands on the company's safety record."
      },
      "workflow": "Weekly pass through the Samsara HOS and unassigned-segments view, assign or annotate each one, reconcile driver log edits, then pull IFTA mileage by jurisdiction out of the dashboard at quarter end.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "A platform update loses corrections that were already entered", "cites": ["src:5"] },
        { "event": "An audit or compliance review is scheduled", "cites": ["src:5"] },
        { "event": "Quarterly fuel tax filing", "cites": ["src:5"] }
      ],
      "who_feels": ["technical_evaluator", "champion"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "One of the cons we experienced is that there was an update done to the system and it wiped out corrections.", "cites": ["src:5"] },
            { "situation": "venting", "verbatim": "The only thing I struggle with in the dashboard is the IFTA.", "cites": ["src:5"] },
            { "situation": "when_it_bites", "verbatim": "No he encontrado como actualizar un estatus a revisado para que se anote que ya fue atendido.", "cites": ["src:5"] }
          ],
          "costs_them": "Recurring hours of clerical cleanup, twice when the data is lost.",
          "fears": "An audit finding on records they thought were already fixed.",
          "dream_outcome": "Segments that assign themselves, corrections that survive updates, and filings that come out of the system ready."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "Static driver assignment issues keep popping up.", "cites": ["src:5"] }
          ],
          "costs_them": "Time that should go to safety work instead of data hygiene.",
          "fears": "A clean-looking dashboard hiding a record that will not survive scrutiny.",
          "dream_outcome": "One screen that shows the compliance record is genuinely clean."
        }
      },
      "segments": ["seg:trucking", "seg:public"],
      "feature_ref": "feat:telematics",
      "cites": ["src:5"]
    },
    {
      "id": "pain:systems-dont-talk",
      "statement": "I was logging into two different sites to answer one question about one truck.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "Telematics, cameras, maintenance, fuel cards and dispatch live in separate tools, and the joining is done in Excel.",
        "operational": "Data gets exported, matched by hand and re-entered, so the answer is always a day old and nobody trusts any single number.",
        "personal": "The admin or coordinator becomes the integration layer, and cannot take a week off without the reporting stopping."
      },
      "workflow": "Pull a report from the Samsara dashboard, export to Excel, match it against fuel card statements and the maintenance system, then rebuild the same sheet next month because scheduled exports are awkward.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Consolidating onto one platform after running two separate logins", "cites": ["src:7"] },
        { "event": "A request for a report the platform will not produce on a schedule", "cites": ["src:5", "src:6"] },
        { "event": "Month-end cost reporting across fuel, maintenance and utilisation", "cites": ["src:7"] }
      ],
      "who_feels": ["technical_evaluator", "economic_buyer", "end_user"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_looking", "verbatim": "one program for all needs. Original product, i had to login to 2 different sights", "cites": ["src:7"] },
            { "situation": "when_it_bites", "verbatim": "No way to automate uploading of information to the server. You have to manually upload files to batch import.", "cites": ["src:6"] },
            { "situation": "when_it_bites", "verbatim": "I think that exporting on a schedule is still a bit confusing.", "cites": ["src:5"] }
          ],
          "costs_them": "A standing manual reconciliation job every week.",
          "fears": "Being the single point of failure for every number leadership sees.",
          "dream_outcome": "One platform of record that feeds the other systems without a human in the middle."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_comparing", "verbatim": "At times the system can feel a bit overwhelming because there are so many features, and it takes some time to fully learn everything", "cites": ["src:7"] }
          ],
          "costs_them": "Decisions made on partial or stale data.",
          "fears": "Buying a platform and still running the spreadsheets.",
          "dream_outcome": "One login, one set of numbers, and a dashboard they can read without training."
        },
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Finding some data can be cumbersome at times.", "cites": ["src:5"] },
            { "situation": "venting", "verbatim": "trying to use it from my phone. i can't see to stay logged in.", "cites": ["src:5"] }
          ],
          "costs_them": "Minutes per lookup, dozens of times a shift.",
          "fears": "Giving dispatch or a customer the wrong answer.",
          "dream_outcome": "The answer on their phone in two taps."
        }
      },
      "segments": ["seg:trucking", "seg:construction", "seg:public"],
      "feature_ref": "feat:platform",
      "cites": ["src:5", "src:6", "src:7"]
    },
    {
      "id": "pain:contract-trap",
      "statement": "We downsized the fleet by a third and they still bill us for every device on the original order.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "Multi-year terms with auto-renewal, per-device pricing that does not shrink, and charges that continue past cancellation.",
        "operational": "Finance fights a billing dispute instead of managing the fleet, and the platform decision becomes irreversible for years regardless of how the business changes.",
        "personal": "The person who signed it has to defend the contract in front of the owner every month it bills."
      },
      "workflow": "Renewal window arithmetic in the contract file, the written cancellation notice, then chasing the ACH pull and the device count on the invoice against the units actually installed.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Business contracts and the fleet shrinks mid-term", "cites": ["src:8"] },
